name: PR Preview Deployment

on:
  pull_request:
    paths:
      - 'website/**'
  workflow_dispatch:

jobs:
  preview:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup .NET
        uses: actions/setup-dotnet@v4
        with:
          dotnet-version: '6.0.x'

      - name: Build and publish website
        run: dotnet publish website/website.csproj -c Release -o website/publish

      - name: Upload artifact
        uses: actions/upload-artifact@v4
        with:
          name: website-preview
          path: website/publish
          retention-days: 30

      - name: Deploy to Cloudflare Pages
        id: cf
        if: ${{ secrets.CLOUDFLARE_API_TOKEN && secrets.CLOUDFLARE_ACCOUNT_ID }}
        uses: cloudflare/pages-action@v1
        with:
          apiToken: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          accountId: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          projectName: website
          directory: website/publish
          branch: ${{ github.head_ref }}

      - name: Set preview URL
        id: preview
        run: |
          if [ -n "${{ steps.cf.outputs.url }}" ]; then
            echo "preview_url=${{ steps.cf.outputs.url }}" >> $GITHUB_OUTPUT
          else
            echo "preview_url=" >> $GITHUB_OUTPUT
          fi

      - name: Post preview comment
        uses: actions/github-script@v6
        env:
          PREVIEW_URL: ${{ steps.preview.outputs.preview_url }}
        with:
          script: |
            const marker = '## Preview Deployment';
            const downloadUrl = `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}/artifacts`;
            const previewUrl = process.env.PREVIEW_URL;
            const commentBody = `
${marker}
**Preview Deployment**

- Artifact: [Download](${downloadUrl})
${previewUrl ? `- Live preview: ${previewUrl}` : ''}
`;
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
            });
            const existing = comments.find(c => c.body.includes(marker));
            if (existing) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existing.id,
                body: commentBody,
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: commentBody,
              });
            }
